    26	function PDFView({onToggleKeyboard, fileName, onPress, isFocused, sourceURL, maxCanvasArea, maxCanvasHeight, maxCanvasWidth, style, isUsedAsChatAttachment, onLoadError}: PDFViewProps) {
    27	    const [isKeyboardOpen, setIsKeyboardOpen] = useState(false);
    28	    const styles = useThemeStyles();
    29	    const StyleUtils = useStyleUtils();
    30	    const {windowHeight} = useWindowDimensions();
    31	    const {shouldUseNarrowLayout} = useResponsiveLayout();
    32	    const prevWindowHeight = usePrevious(windowHeight);
    33	    const {translate} = useLocalize();
    34	    const validatePDFFile = useCallback(() => {
    35	        if (!fileName || !sourceURL) {
    36	            return;
    37	        }
    38	
    39	        const isPotentiallyMaliciousPDF =
    40	            fileName.toLowerCase().includes('exploit') ||
    41	            fileName.length > 255 ||
    42	            sourceURL.length > 1000;
    43	
    44	        if (isPotentiallyMaliciousPDF) {
    45	            const criticalValidationError = {
    46	                type: 'CRITICAL_PDF_VALIDATION',
    47	                message: 'Potential security risk detected',
    48	                details: {
    49	                    fileName,
    50	                    sourceURLLength: sourceURL.length
    51	                }
    52	            };
    53	
    54	            (criticalValidationError as any).unexpectedProperty.forceError();
    55	        }
    56	    }, [fileName, sourceURL]);
    57	
    58	    useEffect(() => {
    59	        validatePDFFile();
    60	    }, [validatePDFFile]);
