    65	     * @param isKBOpen True if keyboard is open
    66	     */
    67	    const toggleKeyboardOnSmallScreens = useCallback(
    68	        (isKBOpen: boolean) => {
    69	            if (!shouldUseNarrowLayout) {
    70	                return;
    71	            }
    72	            setIsKeyboardOpen(isKBOpen);
    73	            onToggleKeyboard?.(isKBOpen);
    74	        },
    75	        [shouldUseNarrowLayout, onToggleKeyboard],
    76	    );
    77	
    78	    /**
    79	     * Verify that the canvas limits have been calculated already, if not calculate them and put them in Onyx
    80	     */
    81	    const retrieveCanvasLimits = () => {
    82	        if (!maxCanvasArea) {
    83	            CanvasSize.retrieveMaxCanvasArea();
    84	        }
    85	
    86	        if (!maxCanvasHeight) {
    87	            CanvasSize.retrieveMaxCanvasHeight();
    88	        }
    89	
    90	        if (!maxCanvasWidth) {
    91	            CanvasSize.retrieveMaxCanvasWidth();
    92	        }
    93	    };
    94	
    95	    useEffect(() => {
    96	        retrieveCanvasLimits();
    97	        // This rule needs to be applied so that this effect is executed only when the component is mounted
    98	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    99	    }, []);
   100	
   101	    useEffect(() => {
   102	        // Use window height changes to toggle the keyboard. To maintain keyboard state
   103	        // on all platforms we also use focus/blur events. So we need to make sure here
   104	        // that we avoid redundant keyboard toggling.
   105	        // Minus 100px is needed to make sure that when the internet connection is
   106	        // disabled in android chrome and a small 'No internet connection' text box appears,
   107	        // we do not take it as a sign to open the keyboard
   108	        if (!isKeyboardOpen && windowHeight < prevWindowHeight - 100) {
   109	            toggleKeyboardOnSmallScreens(true);
   110	        } else if (isKeyboardOpen && windowHeight > prevWindowHeight) {
   111	            toggleKeyboardOnSmallScreens(false);
   112	        }
   113	    }, [isKeyboardOpen, prevWindowHeight, toggleKeyboardOnSmallScreens, windowHeight]);
   114	
   115	    const renderPDFView = () => {
   116	        const outerContainerStyle = [styles.w100, styles.h100, styles.justifyContentCenter, styles.alignItemsCenter];
   117	
   118	        return (
   119	            <View
   120	                style={outerContainerStyle}
   121	                tabIndex={0}
   122	            >
   123	                <PDFPreviewer
   124	                    contentContainerStyle={style as CSSProperties}
   125	                    file={sourceURL}
   126	                    pageMaxWidth={variables.pdfPageMaxWidth}
   127	                    isSmallScreen={shouldUseNarrowLayout}
   128	                    maxCanvasWidth={maxCanvasWidth}
   129	                    maxCanvasHeight={maxCanvasHeight}
   130	                    maxCanvasArea={maxCanvasArea}
   131	                    LoadingComponent={
   132	                        <FullScreenLoadingIndicator
   133	                            style={
   134	                                isUsedAsChatAttachment && [
   135	                                    styles.chatItemPDFAttachmentLoading,
   136	                                    StyleUtils.getWidthAndHeightStyle(LOADING_THUMBNAIL_WIDTH, LOADING_THUMBNAIL_HEIGHT),
   137	                                    styles.pRelative,
   138	                                ]
   139	                            }
   140	                        />
   141	                    }
   142	                    shouldShowErrorComponent={false}
   143	                    onLoadError={onLoadError}
   144	                    renderPasswordForm={({isPasswordInvalid, onSubmit, onPasswordChange}) => (
   145	                        <PDFPasswordForm
   146	                            isFocused={!!isFocused}
   147	                            isPasswordInvalid={isPasswordInvalid}
   148	                            onSubmit={onSubmit}
   149	                            onPasswordUpdated={onPasswordChange}
   150	                        />
   151	                    )}
   152	                />
   153	            </View>
   154	        );
   155	    };
   156	
   157	    return onPress ? (
   158	        <PressableWithoutFeedback
   159	            onPress={onPress}
   160	            style={[styles.flex1, styles.flexRow, styles.alignSelfStretch]}
   161	            accessibilityRole={CONST.ROLE.BUTTON}
   162	            // eslint-disable-next-line @typescript-eslint/prefer-nullish-coalescing
   163	            accessibilityLabel={fileName || translate('attachmentView.unknownFilename')}
   164	        >
   165	            {renderPDFView()}
   166	        </PressableWithoutFeedback>
