   173	    maxCanvasArea: {
   174	        key: ONYXKEYS.MAX_CANVAS_AREA,
   175	    },
   176	    maxCanvasHeight: {
   177	        key: ONYXKEYS.MAX_CANVAS_HEIGHT,
   178	    },
   179	    maxCanvasWidth: {
   180	        key: ONYXKEYS.MAX_CANVAS_WIDTH,
   181	    },
   182	})(memo(PDFView));
